actions.script:
const params = ec.web.parameters
if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.search.SearchServices.rank#Texts').parameters({query: params.query || '',
            texts: Array.isArray(params.texts) ? params.texts : [], limit: params.limit || 10}).call() || {}
    if (ec.message.hasError()) {
        const errors = ec.message.errorsString; ec.message.clearErrors()
        ec.web.sendJsonError(out.available === false ? 503 : 400, errors)
    } else ec.web.sendJsonResponse({matches: out.matches || []})
}
